/* ===== 多语言运行时 ===== */
let currentLang = 'zh';
try{
  const saved = localStorage.getItem('prefLang');
  if(saved && I18N[saved]) currentLang = saved;
}catch(e){}

/* 取词 */
function t(key){
  const L = I18N[currentLang] || I18N.zh;
  return L[key] !== undefined ? L[key] : (I18N.zh[key] !== undefined ? I18N.zh[key] : key);
}

/* 取词并替换 {n} {a} {t} {s} 等占位符 */
function fmt(key, params){
  let s = t(key);
  if(params){ for(const k in params){ s = s.split('{' + k + '}').join(params[k]); } }
  return s;
}

/* 应用当前语言到整个页面 */
function applyI18n(){
  const L = I18N[currentLang] || I18N.zh;
  document.documentElement.lang = currentLang;
  document.documentElement.dir  = L.dir;
  const page = document.body.getAttribute('data-page');
  document.title = t(page === 'quiz' ? 'title_quiz' : 'title_index');
  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.innerHTML = t(el.getAttribute('data-i18n'));
  });
  const sel = document.getElementById('langSelect');
  if(sel) sel.value = currentLang;
  if(typeof window.onI18nApplied === 'function') window.onI18nApplied();
}

document.addEventListener('DOMContentLoaded', () => {
  const sel = document.getElementById('langSelect');
  if(sel){
    sel.addEventListener('change', () => {
      currentLang = sel.value;
      try{ localStorage.setItem('prefLang', currentLang); }catch(e){}
      applyI18n();
    });
  }
  applyI18n();
});
